【例 1.10】有如下递归算法，分析调用 maxelem $ (a,0,n-1) $  的空间复杂度。int maxelem(int a[], int i, int j)
{
int mid = (i + j) / 2, max1, max2;
if (i < j)
{
max1 = maxelem(a, i, mid);
max2 = maxelem(a, mid + 1, j);
return (max1 >max2) ?max1 : max2;
}
else return a[i];
}  
