}int midnum(int a[], int s1, int t1, int b[], int s2, int t2)
{
// 求两个有序序列 a[s1..t1] 和 b[s2..t2] 的中位数
int m1, m2;
if (s1 == t1 && s2 == t2) // 两个序列只有一个元素时返回较小者
return a[s1] < b[s2] ?a[s1] : b[s2];
else
{m1 = (s1 + t1) / 2; // 求 a 的中位数
m2 = (s2 + t2) / 2; // 求 b 的中位数
if (a[m1] == b[m2]) // 两中位数相等时返回该中位数
return a[m1];
