{
postpart(s1, t1); // a 取后半部分
prepart(s2, t2); // b 取前半部分
return midnum(a, s1, t1, b, s2, t2);
}
else // 当 a[m1] >b[m2] 时
{prepart(s1, t1); // a 取前半部分
postpart(s2, t2); // b 取后半部分
return midnum(a, s1, t1, b, s2, t2);
}
}
}  
