bool exchange;
for (i = 0; i < n - 1; i++) // 进行 n-1 趟排序
{
exchange = false; // 本趟排序前置 exchange 为 false
for (j = n - 1; j >i; j--) // 无序区元素比较，找出最小元素
if (a[j] < a[j - 1]) // 当相邻元素反序时
{
swap(a[j], a[j - 1]); //

a[j] 与 a[j - 1] 进行交换
exchange = true; // 本趟排序发生交换置 exchange 为 true
}
if (exchange == false) // 本趟未发生交换时结束算法
return;
}
}
