{
i++;
j++;
}
else // 比较的两个字符不相同时
{
i = i - j + 1; // i 回退
j = 0; // j 从 0 开始
}
if (j == t.length())
{
num++; // 出现次数增 1
j = 0; // j 从 0 开始继续
}
}
return num;
}

