(5) 若第 1 个皇后的所有位置回溯完毕, 则算法结束。(6) 放置第 i 个皇后应与前面已经放置的 i-1 个皇后不发生冲突。采用非递归回溯框架设计的完整程序如下：  
#include <stdio.h>
#include <stdlib.h>  
#define MAXN20 // 最多皇后个数
int q[MAXN]; // 存放各皇后所在的列号，为全局变量
int count = 0; // 累计解个数  
void dispasolution(int n) // 输出一个解
{
printf("第%d个解：", ++count);
for (int i = 1; i <= n; i++)
printf("%d,%d", i, q[i]);
printf("\n");
}  
bool place(int i) // 测试第 i 行的 q[i] 列上能否摆放皇后
{

int j = 1;
if (i == 1) return true;
while (j < i)//j = 1 ~ i -1 是已放置了皇后的行
{
if ((q[j] == q[i]) || (abs(q[j] -q[i]) == abs(j - i)))
// 该皇后是否与以前的皇后同列，位置 (j, q[j]) 与 (i, q[i])

是否同对角线
return false;
j++;
}
return true;
}  
void Queens(int n) // 求解 n 皇后问题
{
int i = 1; // i 表示当前行，也表示放置第 i 个皇后
q[i] = 0; // q[i] 是当前列，每个新考虑的皇后的初始位置置为 0 列
while (i >= 1) // 尚未回溯到头，循环
{
q[i]++; // 原位置后移一列
while (q[i] <= n && !place(i)) // 试探一个位置 (i, q[i])
q[i]++;
if (q[i] <= n) // 为第 i 个皇后找到了一个合适位置 (i, q[i])
{
if (i == n) // 若放置了所有皇后，输出一个解
dispasolution(n);
else // 皇后没有放置完
{
i++; // 转向下一行，即开始下一个新皇后的放置
q[i] = 0; // 每个新考虑的皇后的初始位置置为 0 列
}
}
else i--; // 若第 i 个皇后找不到合适的位置，则回溯到上一个皇后
}
}  
void main()
{
int n; // n 存放实际的皇后个数
scanf("%d", &n);
printf("%d 皇后问题求解如下：\n", n);
Queens(n);
}上述程序与 2.3.2 小节程序的执行结果完全相同。实际上 2.3.

