#include <stdio.h>
#include <algorithm>
using namespace std;  
#define max(x,y)((x)>(y)?

(x):(y))  
#define N 100  
//问题表示  
int n=4;
int a[N] = {5,12,4,8}; //对应 M1 的时间
int b[N] = {6,2,14,7}; //对应 M2 的时间  
struct NodeType
{
int no; //作业序号
bool group; //1 代表第一组 N1,0 代表第二组 N2
int time; //a、b 的最小时间
bool operator < ( const NodeType &s) const
{
return time < s.time; //按 time 递增排序
}
};  
//求解结果表示
int best[N]; //最优调度序列
int solve()
{
int i,j,k;
NodeType c[N];
for(i=0;i<n;i++) //在 n 个作业中求出每个作业的最小加工时间
{
c[i].no=i;
c[i].group=(a[i]<=b[i]); //a[i]<=b[i]对应第 1 组 N1,a[i]>b[i]对应第 0 组 N2
c[i].

time=a[i]<=b[i]?a[i]:b[i]; //第 1 组存放 a[i],第 0 组存放 b[i]
}
sort(c,c+n); //c 中元素按 time 递增排序
j=0; k=n-1;
for(i=0;i<n;i++) //扫描 c 的所有元素,产生最优调度方案
{
if(c[i].group==1) //第 1 组,按 time 递增排列放在 best 的前面部分
best[j++]=c[i].no;
else
best[k--]=c[i].no;
}
int f1=0; //累计 M1 上的执行时间
int f2=0; //最优调度下的消耗总时间
for(i=0;i<n;i++)
{
f1+=a[best[i]];
f2=max(f2,f1)+b[best[i]];
}
return f2;
}
}  
