{return rand()%(b-a+1)+a;
}
bool place(int i,int j) //测试(i,j)位置能否摆放皇后
{
if (i==1) return true; //第一个皇后总是可以放置
int k=1;
while (k<i) //k=1~i-1是已放置了皇后的行
{
if ((q[k]==j)||(abs(q[k]-j)==abs(i-k)))
return false;
k++;
}
}  
}
return true;  
bool queen(int i, int n) // 放置 1~i 的皇后
{
int count, j;
if (i >

n)
{
dispasolution(n); // 所有皇后放置结束
return true;
}
else
{
count = 0; // 试探次数累计
while (count <= n) // 最多试探 n 次
{
j = randa(1, n); // 产生第 i 行上 1 到 n 列的一个随机数 j
count++;
if (place(i, j)) break; // 在第 i 行上找到一个合适位置 (i, j)
}
