{int j = randa(s, t);
swap(a[j], a[s]);
int i = Partition(a, s, t);
QuickSort(a, s, i - 1);
QuickSort(a, i + 1, t);
}
}  
void main()
{
int n = 10;
int a[] = {2, 5, 1, 7, 10, 6, 9, 4, 3, 8};
printf("排序前：");
disp(a, n);
srand((unsigned)time(NULL)); // 随机种子
QuickSort(a, 0, n - 1);
printf("排序后：");
disp(a, n);
}  
从中看出,舍伍德版的快速排序就是在确定性算法中引入随机性。

4 哈密顿回路</div>  
